-- IF only: block executes when true, completely skipped when false
IF(x > 5)
{
   DISPLAY "big"
}

-- IF/ELSE: exactly ONE block always executes, never both, never neither
IF(score ≥ 90)
{
   DISPLAY "A"
}
ELSE
{
   DISPLAY "not A"
}

-- MULTIPLE SEPARATE IFs: ALL evaluated independently
IF(x > 5) { DISPLAY "A" }    -- checked
IF(x > 3) { DISPLAY "B" }    -- also checked regardless
-- If x=4: A is skipped, B executes → output: B
-- If x=7: BOTH execute → output: A B (two outputs!)

-- NESTED: inner only evaluated when outer directs there
IF(x > 10)
{
   IF(x > 20) { DISPLAY "very large" }
   ELSE { DISPLAY "medium" }
}
ELSE
{
   DISPLAY "small"    -- inner IF never reached from here
}

aList ← [3, 7, 1, 9, 4]

-- Max (init to first element):
max ← aList[1]
FOR EACH item IN aList
{
   IF(item > max) { max ← item }
}
DISPLAY max    -- 9

-- Sum and average:
sum ← 0
FOR EACH item IN aList
{
   sum ← sum + item
}
average ← sum / LENGTH(aList)   -- 24/5 = 4.8

-- Linear search:
target ← 9
found ← false
FOR EACH item IN aList
{
   IF(item = target) { found ← true }
}
DISPLAY found   -- true (loop continues to end even after finding)

-- Build filtered list:
newList ← []
FOR EACH item IN aList
{
   IF(item > 4) { APPEND(newList, item) }
}
DISPLAY newList   -- [7, 9]

-- Parameters (in declaration) vs Arguments (in call):
PROCEDURE add(a, b)      -- a, b are PARAMETERS
{
   RETURN(a + b)
}
result ← add(3, 5)       -- 3, 5 are ARGUMENTS → a=3, b=5 → returns 8
DISPLAY result           -- displays 8

-- RETURN causes IMMEDIATE exit from procedure:
PROCEDURE classify(n)
{
   IF(n < 0) { RETURN "negative" }   -- immediate return if n<0
   IF(n = 0) { RETURN "zero" }       -- immediate return if n=0
   RETURN "positive"                 -- only reached if n>0
}

-- Nested calls — evaluate innermost first:
z ← add(add(1, 2), add(3, 4))  -- add(1,2)=3, add(3,4)=7, add(3,7)=10
DISPLAY z    -- 10

-- Code reuse without duplication:
PROCEDURE getLetterGrade(score)
{
   IF(score ≥ 90) { RETURN "A" }
   IF(score ≥ 80) { RETURN "B" }
   IF(score ≥ 70) { RETURN "C" }
   RETURN "F"
}
